class MosaicHost;

// The effect kinds this library answers unless an app claims them.
QSet<QString> mosaicStandardEffectKinds();

// The largest file `files.open` reads, and the largest payload `files.save`
// writes (UI59, UI87 §3.1) -- the same as every other host.
constexpr qint64 MosaicMaxOpenBytes = 50LL * 1024 * 1024;
constexpr qint64 MosaicMaxSaveBytes = 16LL * 1024 * 1024;

// The two dialogs, behind an interface so a test can answer them without a
// display. Each returns the chosen path, or an empty string when the person
// cancelled.
class MosaicFileDialogs
{
public:
    virtual ~MosaicFileDialogs() = default;
    virtual QString chooseFileToOpen(const QStringList &extensions) = 0;
    virtual QString chooseFileToSave(const QString &suggestedName,
                                     const QStringList &extensions) = 0;
};

// `QFileDialog`'s own, when the build links Qt Widgets; null otherwise, and
// then every standard kind fails with a message instead of waiting.
std::shared_ptr<MosaicFileDialogs> mosaicSystemFileDialogs();

// Route one effect: true for this library, false for the app's handler, and
// no value when nobody here should answer it.
std::optional<bool> mosaicRoutesToPlatform(const QString &kind,
                                           const std::optional<QSet<QString>> &appKinds);

// UI87 §3.1's plain file name, checked exactly as the other hosts check it.
bool mosaicIsPlainFileName(const QString &name);
// True when `name` ends in an extension that runs when opened.
bool mosaicHasExecutableExtension(const QString &name);
QSet<QString> mosaicExecutableExtensions();
// Windows device names (`CON`, `NUL.txt`, `com1.json`): never a plain name,
// on any host.
bool mosaicIsReservedDeviceName(const QString &name);
QSet<QString> mosaicReservedDeviceNames();

// Whether every extension the open dialog filters on is an image's, so it can
// start in the Pictures folder (UI59 §2: a caller that wants "pictures only"
// accepts image types, and the dialog's start location follows). No filter at
// all is not "only images": it means any file, and the dialog starts where
// Qt's own default puts it.
//
//     accept                         extensions        start
//     ["image/png", "image/jpeg"]    png jpg jpeg      Pictures
//     ["image/png", "text/plain"]    png txt           Qt's default
//     []                             (none)            Qt's default
bool mosaicOnlyImages(const QStringList &extensions);

// The outcome maps, never an exception.
QVariantMap mosaicRunFilesOpen(const QVariant &payload, MosaicFileDialogs &dialogs);
QVariantMap mosaicRunFilesSave(const QVariant &payload, MosaicFileDialogs &dialogs);

// Install the router on `host`. `appKinds` is the app's `[host_effects]`
// `kinds`, or no value when it declared none. `dialogs` defaults to
// `mosaicSystemFileDialogs()`. Idempotent: a second call changes nothing.
void installMosaicPlatformEffects(MosaicHost &host,
                                  std::optional<QSet<QString>> appKinds,
                                  std::shared_ptr<MosaicFileDialogs> dialogs = nullptr);

